function savedPage(){const list=homes.filter(h=>state.saved.includes(h.id));return `<div class="page-header"><div><div class="eyebrow">YOUR SHORTLIST</div><h1>Feels like home.</h1><p>Keep your favourites in one place. Compare the details when you’re ready.</p></div><button class="outline-btn" data-action="explore">Keep exploring ${icon('arrow')}</button></div>${list.length?`<div class="listing-grid">${list.map(card).join('')}</div>`:`<div class="empty-state">${icon('heart')}<h2>Your next home starts with a favourite.</h2><p>Tap the heart on a home you like.<br>It’ll be waiting here when you come back on this browser.</p><button class="primary-btn" data-action="explore">Explore homes ${icon('arrow')}</button></div>`}`}
function alertMatches(a){return homes.filter(h=>(!a.area||h.area===a.area)&&h.rent<=a.budget&&(!a.fair||fair(h))).length}
function alertsPage(){return `<div class="page-header"><div><div class="eyebrow">A LITTLE HEAD START</div><h1>Good homes, on your radar.</h1><p>Your saved search preferences, ready for the next good find.</p></div><button class="primary-btn" data-action="new-alert">${icon('bell')}Create alert</button></div><div class="notice" style="margin-bottom:23px">Prototype alerts are saved on this browser. Live monitoring, email and push notifications aren’t connected.</div>${state.alerts.length?state.alerts.map(a=>`<article class="alert-card"><div><h3>${esc(a.name)}</h3><p>${esc(a.area||'All Southampton')} · Up to ${money(a.budget)} / person / week${a.fair?' · Fair rent only':''}</p><span class="alert-status">Search saved</span><div class="alert-match">${alertMatches(a)} matching sample homes</div></div><button class="outline-btn" data-delete-alert="${a.id}" aria-label="Delete ${esc(a.name)}">${icon('close')}Delete</button></article>`).join(''):`<div class="empty-state">${icon('bell')}<h2>Let your next home find you.</h2><p>Create a search preference for your budget and area.<br>This demo keeps it ready for you on this browser.</p><button class="primary-btn" data-action="new-alert">Create your first alert</button></div>`}`}
function budgetPage(){return `<div class="page-header"><div><div class="eyebrow">KNOW THE WHOLE PICTURE</div><h1>Rent is only the beginning.</h1><p>A simple planner to make the full cost of your next home a little clearer.</p></div></div><div class="budget-grid"><form class="panel" id="budgetForm"><h2>Build your budget</h2><div class="form-group"><label for="calcRent">Weekly rent, per person</label><div class="input-with-unit"><span>£</span><input id="calcRent" type="number" min="0" max="2000" value="112" required><span>/ week</span></div></div><div class="form-group"><label for="calcBills">Estimated bills, per person</label><div class="input-with-unit"><span>£</span><input id="calcBills" type="number" min="0" max="1000" value="25" required><span>/ week</span></div><div class="helper">Energy, water, broadband and any other costs. Enter 0 if fully included.</div></div><div class="form-group"><label for="calcWeeks">Tenancy length</label><select id="calcWeeks"><option value="52">52 weeks</option><option value="51">51 weeks</option><option value="48">48 weeks</option><option value="44">44 weeks</option></select></div><div class="form-group"><label for="calcDeposit">Deposit to set aside</label><div class="input-with-unit"><span>£</span><input id="calcDeposit" type="number" min="0" max="10000" value="450"><span>upfront</span></div></div><div class="helper">Change any amount to update your estimate. Your actual contract and bills may differ.</div></form><section class="panel budget-result" id="budgetResult" aria-live="polite"></section></div><div class="insight-banner"><div class="insight-icon">${icon('info')}</div><div><h3>Keep a little breathing room.</h3><p>This covers housing costs only. Remember to budget for food, transport and the things that make student life yours.</p></div></div>`}
function render(){const pages={explore:explore,saved:savedPage,alerts:alertsPage,budget:budgetPage};const extra=typeof extraPages==='undefined'?{}:extraPages;const fn=extra[state.page]||pages[state.page]||explore;document.title=state.page.charAt(0).toUpperCase()+state.page.slice(1)+' — Rent Radar';$('#main').innerHTML=fn();$$('.nav-link').forEach(n=>{n.classList.toggle('active',n.dataset.page===state.page);if(n.dataset.page===state.page)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current')});$('#saveCount').textContent=state.saved.length;$('#alertDot').hidden=!state.alerts.length;$('#sidebar').classList.remove('open');if(state.page==='budget')updateBudget();if(typeof afterExtraRender==='function')afterExtraRender();renderTray()}

function updateBudget(){let rent=Math.max(0,Number($('#calcRent').value)||0),bills=Math.max(0,Number($('#calcBills').value)||0),weeks=Number($('#calcWeeks').value),deposit=Math.max(0,Number($('#calcDeposit').value)||0);$('#budgetResult').innerHTML=`<div class="eyebrow">YOUR ESTIMATED HOUSING BUDGET</div><div class="budget-total">${money((rent+bills)*52/12)}<small> / calendar month</small></div><div class="helper">Monthly equivalent = weekly cost × 52 ÷ 12</div><div class="cost-row"><span>Rent over ${weeks} weeks</span><strong>${money(rent*weeks)}</strong></div><div class="cost-row"><span>Bills over ${weeks} weeks</span><strong>${money(bills*weeks)}</strong></div><div class="cost-row"><span>Total tenancy cost</span><strong>${money((rent+bills)*weeks)}</strong></div><div class="deposit-box"><span>Deposit to set aside separately</span><strong>${money(deposit)}</strong></div><div class="helper">The deposit is shown separately from rent and bills. This estimate assumes those weekly costs remain constant.</div>`}
function renderTray(){$('#compareTray').innerHTML=state.compare.length?`<div class="compare-tray">${icon('compare')}<span>${state.compare.length} ${state.compare.length===1?'home':'homes'} to compare</span><button class="text-btn" data-action="clear-compare">Clear</button><button class="primary-btn" data-action="compare">Compare homes ${icon('arrow')}</button></div>`:'';document.body.style.paddingBottom=state.compare.length?'75px':''}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2600)}
function showModal(title,body){$('#modalContent').innerHTML=`<div class="modal-header"><h2>${title}</h2><button class="icon-btn" aria-label="Close dialog" data-action="close">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0}
function closeModal(){$('#modal').close()}
function detail(id,reviews=false){const h=homes.find(x=>x.id===id);if(!h)return;showModal(esc(h.street),`<img class="detail-photo" src="assets/${h.image}" alt="${esc(h.imageAlt)}"><div class="helper photo-credit">Example photo from <a href="https://portswoodstudenthouses.co.uk/about/shakespeare-avenue/" target="_blank" rel="noopener noreferrer">Portswood Student Houses</a>. It shows a separate property; the fictional price, features and reviews below do not describe the photographed home.</div><div class="detail-head"><div><div class="small-kicker">${h.area}, Southampton</div><h3>${esc(h.title)}</h3><p>${h.beds} bedrooms · ${h.baths} shared ${h.baths===1?'bathroom':'bathrooms'} · ${h.walk} min to Highfield (sample)</p></div><button class="outline-btn" data-save="${h.id}">${icon('heart')}${state.saved.includes(h.id)?'Saved':'Save home'}</button></div><div class="detail-columns"><div><h3>About this student house</h3><p>${h.desc}</p><div class="student-feature-list">${h.features.map(f=>`<span>${icon('check')}${esc(f)}</span>`).join('')}</div><div class="student-tenancy"><strong>Example tenancy</strong><span>${h.start} start · ${h.weeks} weeks</span><span>Whole-house group of ${h.beds} · EPC ${h.epc} (sample)</span></div><h3>A clearer view of the rent</h3><p>${money(h.rent+h.bills)} all-in per week ${fair(h)?'sits below':'sits above'} the sample benchmark of ${money(h.benchmark)} all-in for similar sample properties.</p><div class="fair-meter" style="--marker:${fair(h)?'28%':'80%'}"></div><div class="meter-labels"><span>Below typical</span><span>Typical</span><span>Above typical</span></div><p class="helper">Sample model: the median all-in cost of other homes in this neighbourhood, falling back to the wider sample when fewer than two are available. Small, fictional dataset; not a live market valuation.</p></div><div class="detail-rent"><div class="small-kicker">PER PERSON</div><div class="rent-price" style="margin-top:12px">${money(h.rent)}<small> / week</small></div><div class="cost-row"><span>Weekly rent</span><strong>${money(h.rent)}</strong></div><div class="cost-row"><span>${h.included?'Bills included':'Estimated weekly bills'}</span><strong>${money(h.bills)}</strong></div><div class="cost-row"><span>All-in / calendar month</span><strong>${money(monthly(h))}</strong></div><div class="cost-row"><span>Deposit (separate)</span><strong>${money(h.deposit)}</strong></div><div class="helper">Monthly equivalent: weekly total × 52 ÷ 12. Prices are illustrative.</div><button class="primary-btn" data-enquire="${h.id}">Try a viewing enquiry ${icon('arrow')}</button></div></div><section id="tenantReviews"><h3>Hear from the people who lived there</h3><div class="notice">Fictional tenant reviews show the verification concept. Add your own review through the Reviews page; real tenancy evidence is not verified by this demo.</div><div class="review"><div class="review-top">Previous tenant — sample <span>★ ${h.rating.toFixed(1)} / 5</span></div><p>“${h.review}”</p><small>Demo tenancy-confirmed example · fictional, not a real verified testimonial</small></div><button class="outline-btn" data-review="${h.id}">Write a sample review</button><div id="localReviews">${read('reviews-'+h.id,[]).map(r=>`<div class="review"><div class="review-top">${esc(r.name)} <span>★ ${Number(r.rating)} / 5</span></div><p>${esc(r.text)}</p><small>Your local prototype review · unverified</small></div>`).join('')}</div></section>`);if(reviews)setTimeout(()=>$('#tenantReviews').scrollIntoView({behavior:'smooth',block:'start'}),80)}
function newAlert(){showModal('Keep a good home on your radar',`<form id="alertForm" class="modal-form"><p>Choose what matters to you. This prototype saves your search preferences on this browser.</p><div class="form-group"><label for="alertName">Give your alert a name</label><input id="alertName" name="name" required maxlength="70" value="My Southampton home"></div><div class="form-group"><label for="alertArea">Neighbourhood</label><select id="alertArea" name="area"><option value="">All Southampton</option><option>Portswood</option><option>Highfield</option><option>The Polygon</option></select></div><div class="form-group"><label for="alertBudget">Maximum weekly rent / person</label><input id="alertBudget" name="budget" type="number" min="50" max="1000" required value="${state.budget}"></div><label style="font-size:12px;display:flex;align-items:center;gap:8px"><input name="fair" type="checkbox" ${state.fair?'checked':''}>Fair-rent homes only</label><div class="form-actions"><button type="submit" class="primary-btn">${icon('bell')}Save alert</button></div><p class="modal-foot">No emails or push notifications are sent. A live rental feed and notification service would be needed to enable them.</p></form>`)}
function compare(){const list=homes.filter(h=>state.compare.includes(h.id));showModal('A little side-by-side clarity',`<p>Compare per-person housing costs and the details that matter. Select up to three homes from the results.</p><div class="table-scroll"><table class="compare-table"><thead><tr><th>What matters</th>${list.map(h=>`<th><img src="assets/${h.image}" alt="Illustrative interior">${esc(h.street)}<div class="helper">${h.area}</div></th>`).join('')}</tr></thead><tbody>${[['Rent / week',h=>money(h.rent)],['Bills / week',h=>h.included?'Included':money(h.bills)+' estimated'],['All-in / month',h=>money(monthly(h))],['Deposit',h=>money(h.deposit)],['Bedrooms / shared bathrooms',h=>h.beds+' / '+h.baths],['Furnishing',h=>'Furnished, with study desks'],['Example tenancy',h=>h.start+' · '+h.weeks+' weeks'],['Walk to Highfield',h=>h.walk+' min (sample)'],['Price comparison',h=>fair(h)?'Below typical sample rent':'Above typical sample rent'],['Sample tenant rating',h=>h.rating.toFixed(1)+' / 5']].map(([label,fn])=>`<tr><td>${label}</td>${list.map(h=>`<td>${fn(h)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="helper">All figures and reviews are illustrative. Monthly equivalent uses 52 weeks ÷ 12 months. Deposit is separate.</p>`)}
const actions={
'explore':()=>{location.hash='explore'},'alerts':()=>{location.hash='alerts'},'close':closeModal,'menu':()=>$('#sidebar').classList.toggle('open'),'new-alert':newAlert,'compare':compare,
'clear-compare':()=>{state.compare=[];render()},
'reset':()=>{Object.assign(state,{query:'',budget:200,beds:'any',fair:false,bills:false,near:false,type:'any'});render()},
'how':()=>showModal('Your next chapter, with a clearer picture.',`<p>Rent Radar is a student housing concept built to make house-hunting fairer, simpler and less stressful.</p><div class="steps"><div class="step"><span>01</span><h3>Find your place</h3><p>Search by area, budget and bedrooms. Save the homes that feel right for you.</p></div><div class="step"><span>02</span><h3>See the whole cost</h3><p>Compare rent with similar homes, add bills and plan for your deposit.</p></div><div class="step"><span>03</span><h3>Know before you go</h3><p>Read tenant perspectives, compare your shortlist and save a search.</p></div></div><h3>Built around your business model canvas</h3><p>The concept is free for students. A future service could be supported by landlord subscriptions, clearly labelled promoted listings and university partnerships. Paid promotion should never affect the fair-rent assessment.</p><div class="notice">This is an independent prototype. No university partnership, landlord verification or live listing integration is claimed.</div>`),
'data':()=>showModal('A note on this prototype',`<p>Rent Radar brings your business model canvas to life using six fictional Southampton listings. Rents, bills, deposits, walking times, property features, ratings and reviews are fictional examples. Street and neighbourhood names are real, but these are not listings for specific houses. Photos show a separate example student property and must not be read as evidence of the sample features, prices or reviews.</p><h3>Local references and photo credit</h3><p>Student-house photos: <a href="https://portswoodstudenthouses.co.uk/about/shakespeare-avenue/" target="_blank" rel="noopener noreferrer">Portswood Student Houses — Shakespeare Avenue</a>. Local layout and price context: <a href="https://portswoodstudenthouses.co.uk/about/tennyson-road-2/" target="_blank" rel="noopener noreferrer">Tennyson Road example</a>. Copyright remains with the original photographer or publisher. These references do not imply partnership, endorsement or current availability.</p><h3>What you can use</h3><p>Search and filter homes, save favourites, compare up to three homes, calculate housing costs, receive in-app sample matches, extract contract clauses into a one-page PDF, try student and tenancy verification workflows, add landlord demo listings and explore university sample housing insights. Saved items remain on the same browser where storage is available.</p><h3>What a live service would need</h3><p>Licensed property feeds and rent comparables, a validated pricing model, tenancy and landlord verification, review moderation, property imagery, real mapping and an email or push notification service.</p><div class="notice">No enquiries leave this app. Prototype reviews are unverified. No live listings or real-time alerts are provided.</div>`),
'filters':()=>showModal('Find your kind of place',`<form id="filterForm"><div class="filter-modal-fields"><div class="form-group"><label for="filterType">Type of home</label><select id="filterType" name="type"><option value="any">All home types</option><option ${state.type==='Shared house'?'selected':''}>Shared house</option></select></div><div class="form-group"><label for="filterWalk">Distance to Highfield</label><select id="filterWalk" name="near"><option value="no">Any distance</option><option value="yes" ${state.near?'selected':''}>Up to 15 minutes’ walk</option></select></div></div><div class="notice">Walking times are illustrative. Check routes and the location of your own campus before choosing a home.</div><div class="form-actions"><button class="primary-btn" type="submit">Apply filters ${icon('check')}</button></div></form>`)
};
document.addEventListener('click',e=>{let el=e.target.closest('[data-action],[data-save],[data-open],[data-filter],[data-view],[data-compare],[data-delete-alert],[data-enquire],[data-review]');if(!el)return;
if(el.dataset.action){actions[el.dataset.action]?.();return}
if(el.dataset.save){e.stopPropagation();let id=Number(el.dataset.save),saved=state.saved.includes(id);state.saved=saved?state.saved.filter(x=>x!==id):[...state.saved,id];persist('saved',state.saved);if($('#modal').open){const scroll=$('#modal').scrollTop;detail(id);$('#modal').scrollTop=scroll}render();toast(saved?'Removed from your saved homes':'A good find. Saved to your homes.');return}
if(el.dataset.open){detail(Number(el.dataset.open),el.dataset.tab==='reviews');return}
if(el.dataset.filter){state[el.dataset.filter]=!state[el.dataset.filter];render();return}
if(el.dataset.view){state.view=el.dataset.view;render();return}
if(el.dataset.compare){let id=Number(el.dataset.compare);if(state.compare.includes(id))state.compare=state.compare.filter(x=>x!==id);else if(state.compare.length<3)state.compare.push(id);else return toast('Choose up to 3 homes to compare.');render();return}
if(el.dataset.deleteAlert){state.alerts=state.alerts.filter(a=>String(a.id)!==el.dataset.deleteAlert);persist('alerts',state.alerts);render();toast('Search alert deleted');return}
if(el.dataset.enquire){let h=homes.find(x=>x.id===Number(el.dataset.enquire));showModal('Try a viewing enquiry',`<form id="enquiryForm" class="modal-form" data-home="${h.id}"><div class="notice">Practice enquiry for ${esc(h.street)}. This stays on this browser and is not sent to a landlord.</div><div class="form-group" style="margin-top:20px"><label for="enquiryName">Your name</label><input id="enquiryName" name="name" required maxlength="80"></div><div class="form-group"><label for="enquiryMessage">Your message</label><textarea id="enquiryMessage" name="message" required rows="5" maxlength="1500">Hi, I’m interested in ${esc(h.street)}. Could I arrange a viewing and find out more about the tenancy?</textarea></div><button class="primary-btn" type="submit">Save demo enquiry ${icon('arrow')}</button></form>`);return}
if(el.dataset.review){let id=Number(el.dataset.review);showModal('Share a sample tenant review',`<form id="reviewForm" class="modal-form" data-home="${id}"><div class="notice">This review is stored on this browser only. It will be labelled unverified and won’t change the sample rating.</div><div class="form-group" style="margin-top:20px"><label for="reviewName">Display name</label><input id="reviewName" name="name" maxlength="60" required></div><div class="form-group"><label for="reviewRating">Your rating</label><select id="reviewRating" name="rating">${[5,4,3,2,1].map(n=>`<option>${n}</option>`).join('')}</select></div><div class="form-group"><label for="reviewText">What was it like?</label><textarea id="reviewText" name="text" maxlength="1200" rows="4" required></textarea></div><button class="primary-btn" type="submit">Save sample review</button></form>`)}
});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.property-image')){e.preventDefault();detail(Number(e.target.dataset.open))}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,d=new FormData(f);if(f.id==='searchForm'){state.query=String(d.get('location')).trim();state.budget=Number(d.get('budget'));state.beds=d.get('beds');render();toast(`${filtered().length} sample homes found`)}if(f.id==='alertForm'){state.alerts.push({id:Date.now(),name:String(d.get('name')).trim(),area:d.get('area'),budget:Number(d.get('budget')),fair:d.has('fair')});persist('alerts',state.alerts);closeModal();state.page='alerts';location.hash='alerts';render();toast('Your search is on your radar.')}if(f.id==='filterForm'){state.type=d.get('type');state.near=d.get('near')==='yes';closeModal();render()}if(f.id==='enquiryForm'){persist('enquiry-'+f.dataset.home,{name:d.get('name'),message:d.get('message')});showModal('Your practice enquiry is saved',`<div class="empty-state" style="border:0;padding:30px 10px">${icon('check')}<h2>One step closer to your next home.</h2><p>Your draft is saved on this browser.<br>This prototype hasn’t contacted anyone.</p><button class="primary-btn" data-action="close">Back to exploring</button></div>`)}if(f.id==='reviewForm'){let id=Number(f.dataset.home),list=read('reviews-'+id,[]);list.push({name:String(d.get('name')).trim(),rating:Number(d.get('rating')),text:String(d.get('text')).trim()});persist('reviews-'+id,list);detail(id,true);toast('Sample review saved on this browser')}});
document.addEventListener('input',e=>{if(e.target.closest('#budgetForm'))updateBudget()});
document.addEventListener('change',e=>{if(e.target.id==='sort'){state.sort=e.target.value;render()}if(e.target.closest('#budgetForm'))updateBudget()});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
window.addEventListener('hashchange',()=>{state.page=['explore','saved','alerts','budget','contracts','reviews','profile','landlords','university'].includes(location.hash.slice(1))?location.hash.slice(1):'explore';render();window.scrollTo(0,0)});
$('.footer-year').textContent=new Date().getFullYear();state.page=['explore','saved','alerts','budget','contracts','reviews','profile','landlords','university'].includes(location.hash.slice(1))?location.hash.slice(1):'explore';

;
/* Extended browser-local prototype. All external-service states are labelled. */
const extraPages={contracts:contractsPage,reviews:reviewsPage,profile:profilePage,landlords:landlordPage,university:universityPage};
const demoApplicants=[{alias:'Student A',course:'Business Management',group:4,budget:145,status:'Demo verified'},{alias:'Student B',course:'Engineering',group:3,budget:160,status:'Demo verified'},{alias:'Student C',course:'Humanities',group:5,budget:140,status:'Demo verified'}];
let contractDraft='',contractName='Pasted agreement',contractSummary=null,contractReadWarnings=[],contractBusy=false;
let profile=read('student-profile',null),reviewRequests=read('review-requests',[]),alertEvents=read('alert-events',[]);
const seedHomes=homes.filter(h=>!h.userAdded);
function median(numbers){const n=[...numbers].sort((a,b)=>a-b);return n.length%2?n[Math.floor(n.length/2)]:(n[n.length/2-1]+n[n.length/2])/2}
function recalcComparisons(){for(const h of homes){let group=seedHomes.filter(c=>c.id!==h.id&&c.area===h.area);if(group.length<2)group=seedHomes.filter(c=>c.id!==h.id);h.benchmark=Math.round(median(group.map(c=>c.rent+c.bills)));h.comparables=group.length}}
recalcComparisons();
function header(kicker,title,subtitle){return `<div class="page-header"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${subtitle}</p></div></div>`}
function empty(title,text){return `<div class="empty-state">${icon('info')}<h2>${title}</h2><p>${text}</p></div>`}
function downloadFile(name,body,type='text/plain'){const url=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function assetPath(path){return typeof window.rrAsset==='function'?window.rrAsset(path):path}
function contractsPage(){return header('BEFORE YOU SIGN','Your contract. In clearer words.','Find the key clauses, keep the source references and download a one-page overview.')+`<div class="contract-layout"><section class="panel contract-input"><h2>Start with your agreement</h2><p class="helper">Files are read on your device. Contract text is not uploaded or saved by this app.</p><label class="file-drop" for="contractFile">${icon('info')}<strong>Choose a PDF, Word or text file</strong><span>PDF with selectable text, DOCX or TXT · up to 5 MB / 60 PDF pages</span><input id="contractFile" type="file" accept=".pdf,.docx,.txt,text/plain,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document"></label><div class="form-group"><label for="contractText">Or paste your contract text</label><textarea id="contractText" rows="15" maxlength="250000" placeholder="Paste the agreement here. Numbered clauses help keep the source references clear.">${esc(contractDraft)}</textarea></div><div class="action-row"><button class="primary-btn" data-action="summarize-contract" ${contractBusy?'disabled':''}>Create one-page summary ${icon('arrow')}</button><button class="outline-btn" data-action="sample-contract">Try sample</button><button class="text-btn" data-action="clear-contract">Clear</button></div><div id="contractStatus" class="helper" role="status">${contractBusy?'Reading your file…':contractDraft?esc(contractName):'Your document stays in this tab until you clear or close it.'}</div><div class="notice" style="margin-top:18px">This clause finder extracts relevant wording using local rules. It does not provide an AI or legal assessment. Read the original for conditions and exceptions; a missing match does not mean a clause is absent.</div></section><section class="contract-output" id="contractOutput" aria-live="polite">${summaryMarkup()}</section></div>`}
function summaryMarkup(){if(!contractSummary)return `<div class="panel summary-placeholder">${icon('shield')}<h2>The important bits, together.</h2><p>Rent and payment dates. Deposit. Bills. Notice. Repairs. Shared liability.</p><div class="summary-preview-list">${RentRadarContracts.topics.map(t=>`<span>${icon('check')}${t.label}</span>`).join('')}</div><p class="helper">Matched passages are referenced. Items that need clarification stay visible.</p></div>`;const s=contractSummary;return `<div class="panel summary-sheet"><div class="summary-top"><div><div class="eyebrow">EXTRACTED CLAUSE OVERVIEW</div><h2>Your tenancy at a glance</h2><p>${esc(s.name)} · ${s.rows.filter(r=>r.found).length} / ${s.rows.length} topics matched</p></div><button class="outline-btn" data-action="summary-pdf">Download 1-page PDF</button></div>${contractReadWarnings.length?`<div class="notice warning">${esc(contractReadWarnings.join(' '))} Some text could not be read; check the original.</div>`:''}<div class="summary-topic-grid">${s.rows.map(r=>`<article class="summary-topic ${r.found?'':'not-found'}"><h3>${r.label}${r.found?'':' · check'}</h3><p>${esc(r.text)}</p><small>${esc(r.refs.join('; '))}${r.truncated?' · excerpt shortened, check the full clause':''}${r.more?' · '+r.more+' further matching passages':''}</small><details><summary>What to clarify${r.matches.length?' / source passages':''}</summary><p>${esc(r.question)}</p>${r.matches.map(m=>`<blockquote><strong>${esc(m.ref)}</strong><br>${esc(m.text)}</blockquote>`).join('')}</details></article>`).join('')}</div><div class="clarify-box"><h3>Points to clarify</h3>${s.flags.length?s.flags.map(f=>`<p><strong>${f.title}:</strong> ${f.detail} <small>(${esc(f.ref)})</small></p>`).join(''):'<p>No keyword-based flags found. That is not a conclusion that the contract is complete or suitable.</p>'}</div><p class="helper">Extracted wording, not a complete interpretation. Unmatched, shortened and additional passages must be checked in the original. The PDF keeps this overview to one page.</p></div>`}
async function readContractFile(file){if(!file)return;if(file.size>5*1024*1024){toast('Choose a file smaller than 5 MB.');return}contractBusy=true;contractReadWarnings=[];$('#contractStatus').textContent='Reading '+file.name+' locally…';try{const ext=file.name.toLowerCase().split('.').pop();let text='';if(ext==='txt'){text=await file.text()}else if(ext==='docx'){if(!window.mammoth)throw new Error('Word reader unavailable. Paste the text instead.');const r=await mammoth.extractRawText({arrayBuffer:await file.arrayBuffer()});text=r.value;if(r.messages.length)contractReadWarnings.push('The Word reader reported '+r.messages.length+' document warning(s).')}else if(ext==='pdf'){const pdfjs=await import(assetPath('vendor/pdf.min.mjs'));pdfjs.GlobalWorkerOptions.workerSrc=assetPath('vendor/pdf.worker.min.mjs');const task=pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false,useSystemFonts:true});let pdf;try{pdf=await task.promise;if(pdf.numPages>60)throw new Error('Please use a PDF with 60 pages or fewer.');const pages=[];for(let i=1;i<=pdf.numPages;i++){const page=await pdf.getPage(i),tc=await page.getTextContent();let line='',lines=[];for(const it of tc.items){if(typeof it.str!=='string')continue;line+=it.str+' ';if(it.hasEOL){lines.push(line.trim());line=''}}if(line.trim())lines.push(line.trim());const content=lines.join('\n');if(content.replace(/\s/g,'').length<15)contractReadWarnings.push('Page '+i+' has little or no readable text.');pages.push('[Page '+i+']\n'+content)}text=pages.join('\n\n')}finally{await task.destroy()}}else throw new Error('Please choose PDF, DOCX or TXT.');if(text.replace(/\s/g,'').length<40)throw new Error('No usable text found. Scanned PDFs need OCR first; paste the text instead.');if(text.length>250000)throw new Error('This document is too long. Use a shorter copy or paste the relevant text.');contractDraft=text;contractName=file.name;contractSummary=null;if(state.page==='contracts'){$('#contractText').value=text;$('#contractStatus').textContent=file.name+' ready · '+text.length.toLocaleString()+' characters';$('#contractOutput').innerHTML=summaryMarkup()}}catch(err){if(state.page==='contracts')$('#contractStatus').textContent=err.message||'Could not read this document. Paste the text instead.';toast('The document could not be read. See the message below.')}finally{contractBusy=false}}
function summarizeContract(){contractDraft=$('#contractText').value.trim();if(contractBusy)return toast('Wait until the document has finished loading.');if(contractDraft.length<40)return toast('Add at least a paragraph of contract text.');contractSummary=RentRadarContracts.summarize(contractDraft,contractName);$('#contractOutput').innerHTML=summaryMarkup();toast('Clause overview created. Check the source references.')}
function summaryPdf(){if(!contractSummary)return;const {jsPDF}=window.jspdf||{};if(!jsPDF)return toast('PDF export is unavailable.');const doc=new jsPDF({unit:'mm',format:'a4'}),s=contractSummary;doc.setFillColor(31,73,58);doc.rect(0,0,210,33,'F');doc.setTextColor(255);doc.setFontSize(21);doc.text('Your tenancy at a glance',14,16);doc.setFontSize(8);doc.text('RENT RADAR | Extracted clause overview | Check against the original',14,25);doc.setTextColor(45,65,49);doc.setFontSize(8);doc.text(doc.splitTextToSize(s.name.replace(/[^\x20-\x7E£]/g,' '),180).slice(0,1),14,41);const width=86,colX=[14,110];for(let i=0;i<s.rows.length;i++){const r=s.rows[i],col=i<5?0:1,row=i<5?i:i-5,x=colX[col],y=49+row*38;doc.setFillColor(r.found?242:252,r.found?246:244,r.found?237:224);doc.roundedRect(x-2,y-4,90,35,2,2,'F');doc.setFont('helvetica','bold');doc.setFontSize(9);doc.text(r.label,x,y);doc.setFont('helvetica','normal');doc.setFontSize(8);const txt=r.text.replace(/[…]/g,'[...]').replace(/[’‘]/g,"'").replace(/[“”]/g,'"').replace(/[–—]/g,'-');let lines=doc.splitTextToSize(txt,width);const clipped=lines.length>6;lines=lines.slice(0,6);if(clipped)lines[5]=lines[5].slice(0,-12)+' [excerpt]';doc.text(lines,x,y+5);doc.setFontSize(6.5);doc.setTextColor(105,120,95);doc.text(doc.splitTextToSize(r.refs.join('; ')+(clipped||r.truncated?' | shortened - check full clause':''),width).slice(0,2),x,y+28);doc.setTextColor(45,65,49)}let y=211;doc.setFontSize(9);doc.setFont('helvetica','bold');doc.text('Points to clarify',110,y);doc.setFont('helvetica','normal');doc.setFontSize(7.5);const flagText=s.flags.map(f=>f.title+' ('+f.ref+')').join('; ')||'No keyword flags found. This is not a completeness or suitability check.';doc.text(doc.splitTextToSize(flagText,86).slice(0,7),110,y+5);doc.setDrawColor(210,220,200);doc.line(14,254,196,254);doc.setFontSize(7);const foot='One-page extract, not a complete interpretation or legal assessment. Wording may be shortened. Check all matched passages, missing topics, exceptions and additional clauses in the original agreement.'+(contractReadWarnings.length?' WARNING: '+contractReadWarnings.join(' '):'');doc.text(doc.splitTextToSize(foot,180).slice(0,7),14,261);doc.setFontSize(6.5);doc.text('Processed locally | '+new Date().toLocaleDateString('en-GB')+' | 1 / 1',14,288);doc.save('Rent_Radar_Contract_Summary.pdf')}
function profilePage(){const p=profile;return header('YOUR STUDENT PROFILE','A little trust goes a long way.','Show how student verification would work before connecting a real verification service.')+`<div class="workspace-grid"><section class="panel"><h2>Your verification status</h2><div class="status-label ${p?.demo?'status-green':''}">${p?(p.demo?'Verified demo student':'Awaiting verification'):'Not started'}</div><p class="helper">${p?.demo?'This is a fixed fictional profile for trying the app. No person or university email has been verified.':p?'Your details are saved locally; no email has been sent and no identity check has taken place.':'Use a display name and study details to try the request flow. No identity documents are collected.'}</p><form id="profileForm"><div class="form-group"><label for="profileAlias">Display name</label><input id="profileAlias" name="alias" maxlength="60" required value="${esc(p?.alias||'')}"></div><div class="form-group"><label for="profileUni">University</label><select id="profileUni" name="university"><option>University of Southampton</option><option>Southampton Solent University</option><option>Other university</option></select></div><div class="form-group"><label for="profileCourse">Course / programme</label><input id="profileCourse" name="course" maxlength="100" required value="${esc(p?.course||'')}"></div><button class="primary-btn" type="submit">Request student verification</button></form></section><section class="panel"><h2>Try the verified experience</h2><p class="helper">Use a synthetic profile to demonstrate how a student badge and consenting applicant directory could look.</p><div class="demo-profile"><span class="avatar">D</span><div><strong>Demo Student</strong><p>University of Southampton · Business Management</p><span class="status-label status-green">Verified demo profile</span></div></div><button class="outline-btn" data-action="demo-profile">Use fictional verified profile</button><h3>What a real check needs</h3><div class="student-feature-list"><span>${icon('check')}University email confirmation</span><span>${icon('check')}Enrolment evidence or an approved verification provider</span><span>${icon('check')}Explicit consent before sharing with landlords</span></div><div class="notice">A demo badge never confirms a real identity or enrolment.</div></section></div>`}
function reviewsPage(){return header('THE VIEW FROM INSIDE','Hear from previous tenants.','House and landlord experiences, with clear labels for how each review was checked.')+`<div class="notice" style="margin-bottom:22px">The tenancy-confirmed examples below are fictional. Your submitted review stays in this browser with “Awaiting evidence check” status; no automated verification is claimed.</div><div class="workspace-grid"><section><div class="reviews-list">${homes.filter(h=>!h.userAdded).map(h=>`<article class="panel review-tile"><div class="review-top"><strong>${h.street}</strong><span>★ ${h.rating.toFixed(1)}</span></div><span class="status-label status-green">Demo tenancy-confirmed example</span><p>${esc(h.review)}</p><div class="review-meta">House & landlord experience · fictional tenant · sample evidence check</div><button class="text-btn" data-open="${h.id}">See property ${icon('arrow')}</button></article>`).join('')}</div></section><aside><section class="panel"><h2>Share your experience</h2><form id="tenantReviewForm"><div class="form-group"><label for="reviewHome">Which home?</label><select id="reviewHome" name="home">${homes.map(h=>`<option value="${h.id}">${esc(h.street)}</option>`).join('')}</select></div><div class="form-group"><label for="tenantAlias">Display name</label><input id="tenantAlias" name="alias" required maxlength="60"></div><div class="form-group"><label for="tenantRating">Rating</label><select id="tenantRating" name="rating">${[5,4,3,2,1].map(n=>`<option>${n}</option>`).join('')}</select></div><div class="form-group"><label for="tenantReview">House and landlord experience</label><textarea id="tenantReview" name="text" required minlength="15" maxlength="1500" rows="5"></textarea></div><label class="checkbox-line"><input name="consent" type="checkbox" required>I confirm this reflects my experience and want to request a tenancy check.</label><p class="helper">This demo stores text locally. A live service would privately check tenancy evidence and moderate the review before publication.</p><button class="primary-btn" type="submit">Submit for evidence check</button></form></section><section class="panel" style="margin-top:18px"><h2>Your submissions</h2>${reviewRequests.length?reviewRequests.map(r=>`<div class="pending-review"><strong>${esc(homes.find(h=>h.id===r.home)?.street||'Home')}</strong><span class="status-label">Awaiting evidence check</span><p>${esc(r.text)}</p></div>`).join(''):'<p class="helper">No review submissions yet.</p>'}</section></aside></div>`}
function landlordPage(){const added=homes.filter(h=>h.userAdded);return header('LANDLORDS & LETTING AGENTS','Find the right fit for your home.','Manage example listings, see fair-price comparisons and explore a consenting student directory.')+`<div class="notice" style="margin-bottom:22px">Demo workspace · listings and enquiries stay in this browser. Student profiles are fictional. No verification, contact, payment or real listing publication takes place.</div><div class="metric-grid"><div class="metric"><span>Your added listings</span><strong>${added.length}</strong></div><div class="metric"><span>Sample fair-price homes</span><strong>${homes.filter(fair).length}</strong></div><div class="metric"><span>Fictional student groups</span><strong>${demoApplicants.length}</strong></div></div><div class="workspace-grid"><section class="panel"><h2>Add a sample listing</h2><form id="landlordForm"><div class="form-group"><label for="listingStreet">Street or listing name</label><input id="listingStreet" name="street" maxlength="70" required placeholder="e.g. Example Road"></div><div class="filter-modal-fields"><div class="form-group"><label for="listingArea">Neighbourhood</label><select id="listingArea" name="area"><option>Portswood</option><option>Highfield</option><option>The Polygon</option></select></div><div class="form-group"><label for="listingBeds">Bedrooms</label><select id="listingBeds" name="beds">${[3,4,5,6].map(n=>`<option>${n}</option>`).join('')}</select></div><div class="form-group"><label for="listingRent">Rent / person / week (£)</label><input id="listingRent" name="rent" type="number" min="50" max="1000" value="115" required></div><div class="form-group"><label for="listingBills">Extra bills / person / week (£)</label><input id="listingBills" name="bills" type="number" min="0" max="200" value="25" required></div></div><button class="primary-btn" type="submit">Add to demo listings ${icon('arrow')}</button><p class="helper">An in-app alert is created when a newly added demo home matches a saved search. Listings are not uploaded or published to other visitors.</p></form></section><section class="panel"><h2>Student tenant directory</h2><p class="helper">Synthetic, opt-in profile examples. In a live service, access would require student consent and completed checks.</p>${demoApplicants.map(a=>`<div class="applicant-row"><span class="avatar">${a.alias.slice(-1)}</span><div><strong>${a.alias}</strong><p>${a.course} · group of ${a.group} · up to ${money(a.budget)}/week</p><span class="status-label status-green">${a.status}</span></div><button class="outline-btn" data-applicant="${a.alias}">View</button></div>`).join('')}<h3>Your local enquiries</h3>${homes.map(h=>({h,e:read('enquiry-'+h.id,null)})).filter(x=>x.e).map(({h,e})=>`<div class="pending-review"><strong>${esc(h.street)} — ${esc(e.name)}</strong><p>${esc(e.message)}</p><small>Saved locally · not sent</small></div>`).join('')||'<p class="helper">No saved enquiry drafts yet. Try a viewing enquiry from any home.</p>'}</section></div><section class="panel" style="margin-top:24px"><div class="section-heading"><h2>Your added homes</h2><button class="outline-btn" data-action="explore">See all homes</button></div>${added.length?`<div class="listing-grid">${added.map(card).join('')}</div>`:'<p class="helper">Add a sample home to see its automatically calculated price badge.</p>'}</section>`}
function universityStats(area='all'){const list=homes.filter(h=>area==='all'||h.area===area);return {list,median:list.length?median(list.map(h=>h.rent+h.bills)):0,rent:list.length?median(list.map(h=>h.rent)):0,fair:list.filter(fair).length,bills:list.filter(h=>h.included).length}}
function universityPage(){const s=universityStats();return header('UNIVERSITY ACCOMMODATION SERVICES','A clearer picture of student housing.','Explore local housing costs and share better information with students.')+`<div class="notice" style="margin-bottom:22px">Illustrative dashboard from ${homes.length} fictional listings, not a representative survey. No university partnership or access to real student data is claimed.</div><div class="action-row" style="margin-bottom:20px"><label for="insightArea">Neighbourhood</label><select class="compact-select" id="insightArea"><option value="all">All Southampton sample</option><option>Portswood</option><option>Highfield</option><option>The Polygon</option></select><button class="outline-btn" data-action="insights-csv">Download sample data CSV</button></div><div id="insightResults">${insightMarkup(s)}</div><div class="panel" style="margin-top:24px"><h2>Support students before they sign</h2><div class="steps"><div class="step"><span>01</span><h3>Understand costs</h3><p>Compare rent, bills and upfront deposits with the budget planner.</p><a class="text-btn" href="#budget">Open planner →</a></div><div class="step"><span>02</span><h3>Read the agreement</h3><p>Bring important clauses into a source-referenced one-page overview.</p><a class="text-btn" href="#contracts">Open contract checker →</a></div><div class="step"><span>03</span><h3>Hear student experiences</h3><p>Show how moderated, tenancy-confirmed feedback could support decisions.</p><a class="text-btn" href="#reviews">Open reviews →</a></div></div></div>`}
function insightMarkup(s){return `<div class="metric-grid"><div class="metric"><span>Sample homes</span><strong>${s.list.length}</strong></div><div class="metric"><span>Median all-in weekly cost / person</span><strong>${money(s.median)}</strong></div><div class="metric"><span>Fair against sample comparables</span><strong>${s.fair} <small>/ ${s.list.length}</small></strong></div></div><section class="panel" style="margin-top:22px"><h2>Neighbourhood snapshot</h2><div class="table-scroll"><table class="compare-table"><thead><tr><th>Neighbourhood</th><th>Homes</th><th>Median rent / week</th><th>Median all-in / week</th><th>Bills included</th></tr></thead><tbody>${[...new Set(s.list.map(h=>h.area))].map(a=>{const g=s.list.filter(h=>h.area===a);return `<tr><td>${a}</td><td>${g.length}</td><td>${money(median(g.map(h=>h.rent)))}</td><td>${money(median(g.map(h=>h.rent+h.bills)))}</td><td>${g.filter(h=>h.included).length}</td></tr>`}).join('')}</tbody></table></div><p class="helper">Medians use listed rent plus estimated bills per person. Deposits are separate. A small sample and inconsistent bill estimates limit comparisons; badges are demonstrations, not market valuations.</p></section>`}
const originalAlertsPage=alertsPage;
alertsPage=function(){return originalAlertsPage()+`<section class="panel" style="margin-top:24px"><div class="section-heading"><h2>Your in-app matches</h2><button class="outline-btn" data-action="scan-alerts">Check sample listings</button></div><p class="helper">Matches can be checked while this app is open. Adding a demo home in the landlord workspace also checks saved searches. Email, push and background monitoring are not connected.</p>${alertEvents.length?alertEvents.slice().reverse().map(a=>`<div class="alert-event"><div>${icon('bell')}<strong>${esc(a.street)}</strong></div><p>${esc(a.search)} · ${money(a.rent)} / person / week · ${new Date(a.at).toLocaleDateString('en-GB')}</p><button class="text-btn" data-open="${a.home}">View matching home →</button></div>`).join(''):'<p class="helper">No match notifications yet. Create an alert, then check the sample listings.</p>'}</section>`};
function scanAlerts(onlyIds=null){let n=0;for(const a of state.alerts)for(const h of homes){if(onlyIds&&!onlyIds.includes(h.id))continue;if((!a.area||h.area===a.area)&&h.rent<=a.budget&&(!a.fair||fair(h))&&!alertEvents.some(ev=>ev.alert===a.id&&ev.home===h.id)){alertEvents.push({id:Date.now()+n,home:h.id,street:h.street,rent:h.rent,search:a.name,alert:a.id,at:new Date().toISOString()});n++}}persist('alert-events',alertEvents);return n}
function afterExtraRender(){if(state.page==='contracts'&&contractSummary)$('#contractOutput').innerHTML=summaryMarkup()}
Object.assign(actions,{
 'summarize-contract':summarizeContract,'summary-pdf':summaryPdf,
 'sample-contract':()=>{contractDraft=RentRadarContracts.sample;contractName='Fictional sample agreement';contractReadWarnings=[];$('#contractText').value=contractDraft;$('#contractStatus').textContent=contractName;summarizeContract()},
 'clear-contract':()=>{contractDraft='';contractSummary=null;contractName='Pasted agreement';contractReadWarnings=[];render()},
 'demo-profile':()=>{profile={alias:'Demo Student',university:'University of Southampton',course:'Business Management',demo:true};persist('student-profile',profile);render();toast('Fictional verified demo profile selected')},
 'scan-alerts':()=>{const n=scanAlerts();render();toast(n?n+' new in-app sample matches':'No new matches since your last check')},
 'insights-csv':()=>{let area=$('#insightArea')?.value||'all';const rows=universityStats(area).list.map(h=>[h.street,h.area,h.beds,h.baths,h.rent,h.bills,h.rent+h.bills,h.deposit,fair(h)?'Sample fair-price':'Sample above comparison']);downloadFile('Rent_Radar_Sample_Housing_Data.csv','Street,Area,Bedrooms,Bathrooms,Weekly rent per person,Estimated weekly bills,All-in weekly,Deposit,Sample comparison\r\n'+rows.map(r=>r.map(v=>'"'+String(v).replace(/^[=+@\-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n'),'text/csv')}
});
document.addEventListener('input',e=>{if(e.target.id==='contractText'){contractDraft=e.target.value;contractName='Pasted / edited agreement';if(contractSummary){contractSummary=null;$('#contractOutput').innerHTML=summaryMarkup()}}});
document.addEventListener('change',e=>{if(e.target.id==='contractFile')readContractFile(e.target.files[0]);if(e.target.id==='insightArea')$('#insightResults').innerHTML=insightMarkup(universityStats(e.target.value))});
document.addEventListener('click',e=>{const a=e.target.closest('[data-applicant]');if(a){const p=demoApplicants.find(x=>x.alias===a.dataset.applicant);showModal('Fictional student profile',`<h3>${p.alias}</h3><p>${p.course} · group of ${p.group} · budget ${money(p.budget)} per person/week.</p><span class="status-label status-green">Demo verified</span><p>Example consent: this fictional student opted into the demo directory. No real person, contact details or student records are shared.</p><div class="notice">A production directory would require an authenticated landlord, student consent and completed student checks.</div>`)}});
document.addEventListener('submit',e=>{const f=e.target,d=new FormData(f);if(f.id==='profileForm'){profile={alias:String(d.get('alias')).trim(),university:d.get('university'),course:String(d.get('course')).trim(),demo:false,status:'pending'};persist('student-profile',profile);render();toast('Local request saved. Verification is pending.')}if(f.id==='tenantReviewForm'){reviewRequests.push({id:Date.now(),home:Number(d.get('home')),alias:String(d.get('alias')).trim(),rating:Number(d.get('rating')),text:String(d.get('text')).trim(),status:'pending'});persist('review-requests',reviewRequests);render();toast('Review saved locally, awaiting an evidence check')}if(f.id==='landlordForm'){const street=String(d.get('street')).trim(),beds=Number(d.get('beds')),rent=Number(d.get('rent')),bills=Number(d.get('bills'));if(!street||!Number.isFinite(rent)||rent<50||rent>1000||!Number.isFinite(bills)||bills<0||bills>200)return toast('Check the listing details.');const h={id:Date.now(),title:beds+'-bed student house · '+street,street,area:d.get('area'),beds,baths:2,walk:20,rent,bills,deposit:500,benchmark:0,rating:0,reviews:0,image:'student-bedroom.jpg',imageAlt:'Illustrative furnished student bedroom',type:'Shared house',included:bills===0,desc:'A locally added demo listing. Property details and availability have not been checked. Contact and publication are not connected.',review:'No tenant reviews have been submitted for this local demo listing.',landlord:'Your demo account',epc:'Not provided',features:[beds+' furnished bedrooms (sample)','2 shared bathrooms (sample)','Study desks (sample)'],start:'To confirm',weeks:52,userAdded:true};homes.push(h);persist('landlord-homes',homes.filter(x=>x.userAdded));recalcComparisons();const n=scanAlerts([h.id]);render();toast('Demo listing added'+(n?' · '+n+' matching in-app alert(s)':''))}});
render();
